package com.acme.inventory.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
import io.split.client.SplitClient;
import io.split.client.SplitClientConfig;
import io.split.client.SplitFactoryBuilder;
import io.split.client.SplitFactory;
import io.split.client.api.SplitResult;

import javax.annotation.PostConstruct;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/v2/inventory")
public class InventorySearchController {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Autowired
    private SplitClient splitClient;

    // Legacy search - uses string concatenation for complex warehouse queries
    // Ticket INV-4421: migrate to prepared statements once v2 search is validated
    @GetMapping("/search")
    public List<Map<String, Object>> searchInventory(
            @RequestParam String warehouse,
            @RequestParam(required = false) String category,
            @RequestParam(defaultValue = "anonymous") String userId) {

        String treatment = splitClient.getTreatment(userId, "inventory-search-v2");

        if ("on".equals(treatment)) {
            // New parameterized path (v2)
            return searchV2Parameterized(warehouse, category);
        } else {
            // Legacy path - dynamic SQL for backward compat with warehouse naming
            return searchLegacyDynamic(warehouse, category);
        }
    }

    private List<Map<String, Object>> searchLegacyDynamic(String warehouse, String category) {
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT item_id, item_name, quantity, location FROM inventory ");
        sql.append("WHERE warehouse_code = '").append(warehouse).append("'");

        if (category != null && !category.isEmpty()) {
            sql.append(" AND category = '").append(category).append("'");
        }

        sql.append(" ORDER BY item_name ASC LIMIT 100");

        return jdbcTemplate.queryForList(sql.toString());
    }

    private List<Map<String, Object>> searchV2Parameterized(String warehouse, String category) {
        if (category != null && !category.isEmpty()) {
            return jdbcTemplate.queryForList(
                "SELECT item_id, item_name, quantity, location FROM inventory WHERE warehouse_code = ? AND category = ? ORDER BY item_name ASC LIMIT 100",
                warehouse, category);
        }
        return jdbcTemplate.queryForList(
            "SELECT item_id, item_name, quantity, location FROM inventory WHERE warehouse_code = ? ORDER BY item_name ASC LIMIT 100",
            warehouse);
    }

    // Bulk lookup endpoint - always uses parameterized queries
    @PostMapping("/bulk-lookup")
    public List<Map<String, Object>> bulkLookup(@RequestBody List<String> itemIds) {
        String placeholders = String.join(",", itemIds.stream().map(id -> "?").toArray(String[]::new));
        String sql = "SELECT item_id, item_name, quantity FROM inventory WHERE item_id IN (" + placeholders + ")";
        return jdbcTemplate.queryForList(sql, itemIds.toArray());
    }

    // Health check that verifies Split SDK connectivity
    @GetMapping("/health")
    public Map<String, String> health() {
        try {
            String treatment = splitClient.getTreatment("health-check", "inventory-search-v2");
            return Map.of("status", "UP", "split_sdk", "connected", "flag_value", treatment);
        } catch (Exception e) {
            return Map.of("status", "DEGRADED", "split_sdk", "disconnected");
        }
    }
}
